  // Current input value
  const [query, setQuery] = useState(''); // TODO: hold current search query

  // Results, loading, and error state
  const [results, setResults] = useState([]); // TODO: store API results
  const [isLoading, setIsLoading] = useState(false);    // TODO: toggle while request in-flight
  const [error, setError] = useState(null); // TODO: store error messages

  // TODO: Implement debounced search in a useEffect.
  // Requirements:
  // - Wait 500ms after the user stops typing before calling fakeApiSearch(query)
  // - Clear results and flags when query is empty (no API call)
  // - Set isLoading while the debounced request is running
  // - On success: fill results and clear loading
  // - On failure: set error, clear results, clear loading
  // - Use the cleanup function to cancel the timeout / ignore stale responses
  // useEffect(() => {
  //   // your logic here
  // }, [query]);

  const handleChange = (event) => {
    const value = event.target.value;
    setQuery(value);
    // Optional: you may want to clear error here when the user types again.
  };

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Debounced Search</h1>
          <p className="subtitle">Type to search a fake user directory. Search runs 500ms after you stop typing.</p>
        </header>

        <div className="field">
          <label className="label" htmlFor="search-input">Search</label>
          <input
            id="search-input"
            className="input"
            type="text"
            value={query}
            onChange={handleChange}
            placeholder="Start typing a name or email..."
            autoComplete="off"
          />
        </div>

        <div className="status-row">
          {isLoading && <span className="status status--loading">Searching…</span>}
          {!isLoading && !error && query && (
            <span className="status">Showing {results.length} result(s) for "{query}"</span>
          )}
          {!isLoading && !error && !query && (
            <span className="status status--muted">Start typing to search.</span>
          )}
          {error && <span className="status status--error">{error}</span>}
        </div>

        {results.length > 0 && (
