                <div className="result-name">{r.name}</div>
                <div className="result-email">{r.email}</div>
              </li>
            ))}
          </ul>
        )}

        {!results.length && !isLoading && query && !error && (
          <p className="empty">No results found for "{query}".</p>
        )}
      </section>
    </main>
  );
}

